-- Reconexión: adjunta la cobertura municipal nacional de Polícia Federal a los
-- postos que YA existían en la tabla policias (no crea duplicados). Requiere
-- haber corrido antes 005_seed_postos_pf_brasil.sql (versión con estado) para
-- generar la lista de municipios, y haber limpiado los 125 postos duplicados
-- y sus relaciones/ciudades huérfanas (ver instrucciones dadas en el chat).
-- Idempotente: usa NOT EXISTS, seguro de re-ejecutar.

BEGIN;

-- 1) Postos que no tenían contraparte ya cargada (se insertan como nuevos)
INSERT INTO policias (nombre, notas)
SELECT v.nombre, v.notas FROM (VALUES
  ('Jataí - DPF/JTI/GO', 'Sigla: DPF/JTI/GO. Fonte: Tabela de circunscrições PF (gov.br/pf). Circunscrição oficial da Policía Federal para trâmites de migración (CRNM/estrangeiros).')
) AS v(nombre, notas)
WHERE NOT EXISTS (SELECT 1 FROM policias p WHERE p.nombre = v.nombre);

-- 2) Municípios (los 4.936 de antes; NOT EXISTS por nombre+estado)
