JOIN policias p ON p.nombre = v.policia_nombre
JOIN ciudades c ON c.nombre = v.ciudad_nombre AND c.estado IS NOT DISTINCT FROM v.ciudad_estado
WHERE NOT EXISTS (
  SELECT 1 FROM policias_ciudades pc WHERE pc.policia_id = p.id AND pc.ciudad_id = c.id
);

COMMIT;
